mapper.select:
select * from orders


        and shop_id = #{shopId}


        and user_id = #{userId}


        and status = #{status}


        and number = #{number}


        and phone like concat('%', #{phone}, '%')


        and order_time >= #{beginTime}


        and order_time <= #{endTime}


order by order_time desc

select count(id) from orders


        and shop_id = #{shopId}


        and status = #{status}

select DATE_FORMAT(order_time, '%Y-%m-%d') as orderDate, count(id) as orderCount
from orders
where order_time between #{begin} and #{end}

    and shop_id = #{shopId}


    and status = #{status}

group by DATE_FORMAT(order_time, '%Y-%m-%d')
order by orderDate

select DATE_FORMAT(order_time, '%Y-%m-%d') as orderDate, ifnull(sum(amount), 0) as turnover
from orders
where status = 5 and order_time between #{begin} and #{end}

    and shop_id = #{shopId}

group by DATE_FORMAT(order_time, '%Y-%m-%d')
order by orderDate
